def refs():
    return [{**s, "subject": "science", "locator": "人體消化道與消化腺、三大營養素消化、器官順序、小腸絨毛與養分吸收、消化液功能", "observedPattern": "公立學校公開生物科試題常以消化系統圖、養分分解曲線、器官功能與小腸絨毛情境，要求整合部位、物質變化與吸收路徑；本題只採能力方向與資料型態。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


