Q = [
    make(1, "下列哪一項最能正確區分『消化』與『吸收』？", {"A": "消化是把食物中的大分子處理成較小形式；吸收是養分穿過小腸壁進入血液或淋巴", "B": "消化是食物進入口腔；吸收是食物被牙齒咬碎", "C": "消化和吸收都只表示胃的蠕動", "D": "消化是細胞使用養分；吸收是細胞製造養分"}, "消化關注物質被機械或化學方式處理，吸收則有明確的界面事件：可吸收養分穿過小腸壁，進入微血管或乳糜管等運輸系統。", "先抓題幹要求的『物質變化』與『跨越界面』兩個判準，再逐項檢查。", ["圈出消化與吸收兩個名詞。", "確認消化要回答食物分子是否被處理。", "確認吸收要回答養分是否穿過小腸壁。", "排除只描述進食、咀嚼、蠕動或細胞利用的選項。", "所以選 A。"], "easy"),
    make(2, "一口含澱粉的飯進入人體後，哪條敘述最合理？", {"A": "澱粉先在消化道中被分解成可吸收的小分子，之後主要由小腸吸收進入血液", "B": "澱粉只要被牙齒咬碎，就會直接進入細胞", "C": "澱粉在胃中直接變成胺基酸，再由乳糜管運輸", "D": "澱粉不需消化，會以完整大分子穿過小腸壁"}, "澱粉是醣類大分子，需經消化成較小的醣類分子，才能在小腸被吸收；胺基酸是蛋白質的消化產物，不能混用。", "從營養素身分出發，依序檢查消化產物、吸收位置與運輸方式。", ["先辨認飯的主要營養素是澱粉。", "確認澱粉不能以完整大分子直接穿過腸壁。", "找出其消化後的較小醣類形式。", "確認小腸吸收後主要進入微血管血液。", "所以選 A。"], "easy"),
    make(3, "若要追蹤蛋白質從食物到細胞的路徑，下列哪項正確？", {"A": "蛋白質經消化成胺基酸，在小腸吸收後進入血液，再送到細胞利用", "B": "蛋白質被膽汁直接分解成葡萄糖，經乳糜管送到細胞", "C": "蛋白質只在口腔被咀嚼，不會發生化學消化", "D": "完整蛋白質可直接穿過小腸壁，不需分解"}, "蛋白質需經消化酵素分解成胺基酸等較小單位；胺基酸由小腸吸收後進入血液，才能運送到各組織細胞。", "路徑題要同時核對營養素、消化產物、吸收界面與運輸管道。", ["辨認蛋白質不是葡萄糖或脂肪。", "寫出蛋白質消化後的胺基酸。", "確認胺基酸在小腸穿過腸壁。", "確認水溶性小分子主要進入微血管與血液。", "所以選 A。"], "medium"),
    make(4, "膽汁在脂質消化中的主要作用為何？", {"A": "把脂肪分散成較小液滴，增加酵素接觸面；它本身不是消化酵素", "B": "把脂肪直接轉成胺基酸，並在胃中完成吸收", "C": "把所有食物變成葡萄糖，取代小腸的吸收功能", "D": "讓脂肪不必經消化就以完整大分子進入血液"}, "膽汁可乳化脂肪，使脂肪液滴變小、增加脂肪酶的作用面積；膽汁不是把脂肪直接水解成消化產物的酵素。", "看到消化液名稱時，先分辨它是提供酵素還是改善接觸條件。", ["先鎖定題目問的是脂質而非蛋白質。", "確認膽汁的功能是乳化與增加接觸面。", "把膽汁與真正催化分解的脂肪酶區分開。", "排除胺基酸、葡萄糖與完整脂肪直接吸收等錯誤。", "所以選 A。"], "medium"),
    make(5, "小腸內壁具有皺褶與絨毛，最直接有助於哪項功能？", {"A": "增加與腸腔接觸的表面積，提高養分吸收機會", "B": "讓食物在小腸內完全不會前進", "C": "把所有大分子直接變成細胞核", "D": "使小腸取代心臟泵送血液"}, "皺褶與絨毛增加小腸內壁的有效表面積，使消化產物更容易接觸吸收表面；它們不是讓食物停止，也不能取代循環器官。", "結構功能題先找結構造成的幾何改變，再連到最直接的生理結果。", ["觀察皺褶與絨毛都增加表面起伏。", "把表面積增加連到養分接觸與吸收。", "確認題目問的是小腸結構的主要作用。", "排除泵血、停止蠕動與改造細胞核等不相干敘述。", "所以選 A。"], "easy"),
    make(6, "下列哪一個例子主要屬於『機械性消化』，而不是化學性消化？", {"A": "牙齒把食物咬碎，讓食物顆粒變小但分子種類未因此改變", "B": "澱粉酶把澱粉分解成較小的醣類", "C": "蛋白酶把蛋白質切成胺基酸或短鏈片段", "D": "脂肪酶催化脂質分解成脂肪酸與甘油等產物"}, "咀嚼主要改變食物的大小與接觸面，並未直接改變分子種類；酵素催化分解才是化學性消化。", "判斷機械或化學時，不看食物是否變軟，而看分子種類是否因反應而改變。", ["找出每個選項描述的作用者。", "檢查是否只是切割、攪拌、混合或改變大小。", "若出現酵素催化與新產物，判為化學性消化。", "牙齒咬碎沒有產生新的分子種類。", "所以選 A。"], "easy"),
    make(7, "食物從口腔經消化道到達小腸，哪個順序正確？", {"A": "口腔→咽與食道→胃→小腸", "B": "口腔→胃→食道→小腸", "C": "口腔→小腸→胃→食道", "D": "胃→口腔→食道→小腸"}, "食物先由口腔進入，再經咽與食道送到胃，接著進入小腸；器官順序要依消化道的連續管道判斷。", "流程題先畫單向箭頭，再逐一核對相鄰器官是否真的相連。", ["確定食物的起點是口腔。", "找出由口腔通往胃的管道是咽與食道。", "把胃放在食道之後。", "把小腸放在胃之後作為主要消化與吸收部位。", "所以選 A。"], "easy"),
    make(8, "比較水溶性與脂溶性養分的吸收路徑，下列哪項最合理？", {"A": "水溶性小分子多進入小腸絨毛的微血管；部分脂質消化產物先進入乳糜管，再匯入淋巴系統", "B": "所有養分都只能經由氣管進入肺泡，再送到血液", "C": "脂質消化產物一定全部先進入腎小管，水溶性養分才進入小腸", "D": "只要食物到達胃，所有養分便已分流到血液與淋巴"}, "小腸絨毛內有微血管與乳糜管，水溶性小分子常先進入血液；部分脂質相關物質則先進入乳糜管與淋巴，不能把所有養分簡化成同一路徑。", "路徑比較要先看物質性質，再用小腸絨毛內的兩種運輸構造對照。", ["先標出題目比較的是水溶性與脂溶性。", "確認兩者都要在小腸完成主要吸收。", "將水溶性小分子連到微血管與血液。", "將部分脂質相關物質連到乳糜管與淋巴，排除胃、氣管與腎小管。", "所以選 A。"], "hard"),
    make(9, "有人說：『把食物打成液體，就代表養分已經被吸收。』哪項回應最有證據？", {"A": "不能直接如此推論；液體外觀可能只是顆粒變小或混合，仍要證明養分已穿過小腸壁", "B": "一定正確，任何液體都能直接進入血液", "C": "一定錯誤，液體永遠不能被人體吸收", "D": "只要食物在胃中變稀，就代表細胞已經利用養分"}, "打碎或混合可改變外觀與流動性，卻不必然代表大分子已完成化學消化，更不能取代養分穿過小腸壁的吸收證據。", "生活宣稱題要把觀察到的現象與尚未測量的生理事件分開。", ["先寫出宣稱的直接觀察是『變成液體』。", "確認外觀變化不能單獨證明分子種類改變。", "找出吸收的必要證據是跨過小腸壁。", "再區分吸收與細胞真正利用之間的差異。", "所以選 A。"], "medium"),
    make(10, "若要用模型檢查『蛋白質可被吸收並運送到細胞』這個說法，哪組紀錄最完整？", {"A": "記錄蛋白質被分解成胺基酸、胺基酸穿過小腸壁進入血液，以及後續到達細胞的運輸箭頭", "B": "只拍攝食物進入口腔的照片，不記錄物質變化", "C": "只記錄胃的大小，不標示養分形式或移動方向", "D": "看到食物變軟便直接宣布細胞已經合成新物質"}, "完整模型要把分子變化、跨腸壁的吸收事件與運輸方向串起來；只觀察入口、器官大小或食物變軟，都不足以支持細胞利用的結論。", "證據題採『物質—界面—方向—結論限制』四欄檢查。", ["先列出蛋白質消化後的胺基酸。", "標記胺基酸穿過小腸壁的吸收事件。", "畫出進入血液後送往細胞的方向。", "把模型未直接測量的細胞代謝標成後續推論。", "所以選 A。"], "hard"),
]

for index, target in {2: "B", 4: "C", 6: "D", 8: "B", 10: "C"}.items():
    q = Q[index - 1]
    option_map = {o["id"]: o["text"] for o in q["options"]}
    option_map["A"], option_map[target] = option_map[target], option_map["A"]
    q["options"] = [{"id": k, "text": option_map[k]} for k in ("A", "B", "C", "D")]
    q["answer"]["value"] = target
    q["answer"]["explanation"] = q["answer"]["explanation"].replace("選 A。", f"選 {target}。")
    q["solutionSteps"] = [s.replace("所以選 A。", f"所以選 {target}。") for s in q["solutionSteps"]]

for q in Q:
    (OUT / f"{q['id']}.json").write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(Q)} questions")
